CREATE TABLE "allowed_chats" (
  "chat_id" bigint GENERATED BY DEFAULT AS IDENTITY,
  rowid bigint GENERATED ALWAYS AS ("chat_id") STORED,
  PRIMARY KEY ("chat_id")
);

CREATE TABLE "avatars" (
  "kind" text NOT NULL,
  "subject_id" bigint NOT NULL,
  "photo_id" text,
  "path" text,
  "updated_at" bigint NOT NULL,
  rowid bigint GENERATED BY DEFAULT AS IDENTITY UNIQUE,
  PRIMARY KEY ("kind", "subject_id")
);

CREATE TABLE "bmo_room_contexts" (
  "session_id" text,
  "fingerprint" text NOT NULL,
  rowid bigint GENERATED BY DEFAULT AS IDENTITY UNIQUE,
  PRIMARY KEY ("session_id")
);

CREATE TABLE "bmo_rooms" (
  "chat_id" bigint GENERATED BY DEFAULT AS IDENTITY,
  rowid bigint GENERATED ALWAYS AS ("chat_id") STORED,
  PRIMARY KEY ("chat_id")
);

CREATE TABLE "bmo_session_rooms" (
  "session_id" text NOT NULL,
  "chat_id" bigint NOT NULL,
  rowid bigint GENERATED BY DEFAULT AS IDENTITY UNIQUE,
  PRIMARY KEY ("session_id", "chat_id")
);

CREATE TABLE "chat_notices" (
  "chat_id" bigint NOT NULL,
  "kind" text NOT NULL,
  "enabled" bigint NOT NULL,
  rowid bigint GENERATED BY DEFAULT AS IDENTITY UNIQUE,
  PRIMARY KEY ("chat_id", "kind")
);

CREATE TABLE "chat_reads" (
  "chat_id" bigint GENERATED BY DEFAULT AS IDENTITY,
  "last_read_message_id" bigint NOT NULL,
  rowid bigint GENERATED ALWAYS AS ("chat_id") STORED,
  PRIMARY KEY ("chat_id")
);

CREATE TABLE "chat_titles" (
  "chat_id" bigint GENERATED BY DEFAULT AS IDENTITY,
  "title" text NOT NULL,
  rowid bigint GENERATED ALWAYS AS ("chat_id") STORED,
  PRIMARY KEY ("chat_id")
);

CREATE TABLE "collected_items" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY,
  "chat_id" bigint NOT NULL,
  "message_id" bigint NOT NULL,
  "sender_name" text NOT NULL,
  "kind" text NOT NULL,
  "source" text NOT NULL,
  "stored_path" text,
  "summary" text,
  "collected_at" bigint NOT NULL,
  "file_unique_id" text,
  rowid bigint GENERATED ALWAYS AS ("id") STORED,
  PRIMARY KEY ("id"),
  UNIQUE ("chat_id", "message_id", "source")
);

CREATE TABLE "delegate_chats" (
  "chat_id" bigint GENERATED BY DEFAULT AS IDENTITY,
  rowid bigint GENERATED ALWAYS AS ("chat_id") STORED,
  PRIMARY KEY ("chat_id")
);

CREATE TABLE "instructions" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY,
  "chat_id" bigint NOT NULL,
  "text" text NOT NULL,
  "created_at" bigint NOT NULL,
  "delivered_at" bigint,
  "kind" text,
  "expires_at" bigint,
  "handed_at" bigint,
  "restarts" bigint NOT NULL DEFAULT 0,
  "via" text,
  "events" text NOT NULL DEFAULT '',
  "rides" bigint NOT NULL DEFAULT 0,
  "ride_until" bigint,
  "agent" text NOT NULL,
  "sort" text,
  "summary" text,
  "round" text,
  "run_id" bigint,
  rowid bigint GENERATED ALWAYS AS ("id") STORED,
  PRIMARY KEY ("id")
);

CREATE TABLE "messages" (
  "chat_id" bigint NOT NULL,
  "message_id" bigint NOT NULL,
  "sender_id" bigint,
  "sender_name" text NOT NULL,
  "sent_at" bigint NOT NULL,
  "text" text NOT NULL,
  "image_path" text,
  "reply_to_message_id" bigint,
  "answer_seconds" bigint,
  "round" text,
  "album" bigint,
  "via" text,
  rowid bigint GENERATED BY DEFAULT AS IDENTITY UNIQUE,
  PRIMARY KEY ("chat_id", "message_id")
);

CREATE TABLE "muted_members" (
  "chat_id" bigint NOT NULL,
  "user_id" bigint NOT NULL,
  rowid bigint GENERATED BY DEFAULT AS IDENTITY UNIQUE,
  PRIMARY KEY ("chat_id", "user_id")
);

CREATE TABLE "photo_chats" (
  "chat_id" bigint GENERATED BY DEFAULT AS IDENTITY,
  "look" bigint NOT NULL,
  rowid bigint GENERATED ALWAYS AS ("chat_id") STORED,
  PRIMARY KEY ("chat_id")
);

CREATE TABLE "provider_owner_users" (
  "provider" text NOT NULL,
  "chat_id" bigint NOT NULL,
  "user_id" text NOT NULL,
  rowid bigint GENERATED BY DEFAULT AS IDENTITY UNIQUE,
  PRIMARY KEY ("provider", "chat_id", "user_id")
);

CREATE TABLE "provider_private_rooms" (
  "provider" text NOT NULL,
  "chat_id" bigint NOT NULL,
  "sender_id" bigint NOT NULL,
  rowid bigint GENERATED BY DEFAULT AS IDENTITY UNIQUE,
  PRIMARY KEY ("provider", "chat_id")
);

CREATE TABLE "provider_rooms" (
  "provider" text NOT NULL,
  "room_id" text NOT NULL,
  "chat_id" bigint NOT NULL,
  "title" text NOT NULL,
  rowid bigint GENERATED BY DEFAULT AS IDENTITY UNIQUE,
  PRIMARY KEY ("provider", "room_id"),
  UNIQUE ("chat_id")
);

CREATE TABLE "provider_users" (
  "provider" text NOT NULL,
  "user_id" text NOT NULL,
  "sender_id" bigint NOT NULL,
  rowid bigint GENERATED BY DEFAULT AS IDENTITY UNIQUE,
  PRIMARY KEY ("provider", "user_id"),
  UNIQUE ("sender_id")
);

CREATE TABLE "random_draw_rooms" (
  "chat_id" bigint GENERATED BY DEFAULT AS IDENTITY,
  "next_seed" text NOT NULL,
  "next_commitment" text NOT NULL,
  rowid bigint GENERATED ALWAYS AS ("chat_id") STORED,
  PRIMARY KEY ("chat_id")
);

CREATE TABLE "random_draws" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY,
  "chat_id" bigint NOT NULL,
  "via" text,
  "message_id" bigint,
  "mode" text NOT NULL,
  "shape" text NOT NULL,
  "spec" text NOT NULL,
  "label" text,
  "commitment" text,
  "seed" text NOT NULL,
  "result" text NOT NULL,
  "next_commitment" text NOT NULL,
  "method" text NOT NULL,
  "created_at" bigint NOT NULL,
  rowid bigint GENERATED ALWAYS AS ("id") STORED,
  PRIMARY KEY ("id")
);

CREATE TABLE "reload_pending" (
  "chat_id" bigint NOT NULL,
  "path" text NOT NULL,
  rowid bigint GENERATED BY DEFAULT AS IDENTITY UNIQUE,
  PRIMARY KEY ("chat_id", "path")
);

CREATE TABLE "reload_sent" (
  "chat_id" bigint GENERATED BY DEFAULT AS IDENTITY,
  "at" bigint NOT NULL,
  rowid bigint GENERATED ALWAYS AS ("chat_id") STORED,
  PRIMARY KEY ("chat_id")
);

CREATE TABLE "room_answerers" (
  "chat_id" bigint NOT NULL,
  "agent" text NOT NULL,
  rowid bigint GENERATED BY DEFAULT AS IDENTITY UNIQUE,
  PRIMARY KEY ("chat_id", "agent")
);

CREATE TABLE "run_records" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY,
  "run" text NOT NULL,
  "kind" text NOT NULL,
  "text" text NOT NULL,
  "record_id" bigint,
  "wakes" bigint NOT NULL DEFAULT 0,
  "at" bigint NOT NULL,
  rowid bigint GENERATED ALWAYS AS ("id") STORED,
  PRIMARY KEY ("id")
);

CREATE TABLE "say_relays" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY,
  "chat_id" bigint NOT NULL,
  "reply_to" bigint NOT NULL,
  "opening" text NOT NULL,
  "created_at" bigint NOT NULL,
  "expires_at" bigint NOT NULL,
  "delivered_at" bigint,
  rowid bigint GENERATED ALWAYS AS ("id") STORED,
  PRIMARY KEY ("id")
);

CREATE TABLE "settings" (
  "key" text,
  "value" text NOT NULL,
  rowid bigint GENERATED BY DEFAULT AS IDENTITY UNIQUE,
  PRIMARY KEY ("key")
);

CREATE TABLE "tool_chats" (
  "chat_id" bigint GENERATED BY DEFAULT AS IDENTITY,
  rowid bigint GENERATED ALWAYS AS ("chat_id") STORED,
  PRIMARY KEY ("chat_id")
);

CREATE INDEX "instructions_pending" ON "instructions" (id) WHERE delivered_at IS NULL AND handed_at IS NULL;

CREATE INDEX "instructions_round" ON "instructions" ("round");

CREATE INDEX "instructions_run" ON "instructions" ("run_id") WHERE "run_id" IS NOT NULL;

CREATE INDEX "messages_round" ON "messages" (chat_id, round);

CREATE INDEX "messages_sender" ON "messages" (sender_id, chat_id);

CREATE INDEX "messages_sender_latest" ON "messages" (chat_id, sender_id, sent_at);

CREATE INDEX "messages_unnamed" ON "messages" (chat_id) WHERE via IS NULL;

CREATE INDEX "random_draws_chat" ON "random_draws" (chat_id, id);

CREATE INDEX "run_records_run" ON "run_records" (run, id);

CREATE INDEX "say_relays_asker" ON "say_relays" (reply_to, created_at);

CREATE INDEX "say_relays_chat" ON "say_relays" (chat_id, delivered_at);
